INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('omens', 'state', '«اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُكَ، وَلَا طَيْرَ إِلَّا طَيْرُكَ، وَلَا إِلَهَ غَيْرُكَ»', 'O Allaah, er is geen goed behalve Uw goed, geen voorteken behalve Uw beschikking, en er is geen god buiten U.', 'O Allaah, there is no good except Your good, no omen except Yours, and there is no god other than You.', '', '', '', 'الفضل مبين: هو كفارة الطيرة المنصوصة.', 'De verdienste is toegelicht: het is de vastgestelde boetedoening voor het voorteken (tiyarah).', 'The merit is explained: it is the prescribed expiation for the omen (tiyarah).', 'كفارة الطيرة أن يقول', 'toestand', 'state/situation', 1, 201),('joy', 'state', 'خرّ ساجدا شكرا لله تبارك وتعالى', 'Bij verheugend nieuws knielt men in dankbaarheid neer voor Allaah (soedjoed as-shukr).', 'At glad news one falls in prostration of gratitude to Allaah.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'كان ﷺ إذا أتاه أمر يَسُرّه أو بُشّر به', 'toestand', 'state/situation', 1, 202),('gratitude', 'state', '«جَزَاكَ اللَّهُ خَيْرًا»', 'Moge Allaah jou met het goede belonen — daarmee is de dank ten volle uitgesproken.', 'May Allaah reward you with good — with this, gratitude is fully expressed.', '', '', '', 'الفضل منصوص: «فقد أبلغ في الثناء».', 'De verdienste is uitdrukkelijk: ''hij heeft de lof ten volle uitgesproken''.', 'The merit is stated: ''he has fully expressed the praise''.', 'الدعاء لمن أسدى معروفا', 'toestand', 'state/situation', 1, 203),('gratitude', 'state', '«اللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ، وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ»', 'O Allaah, vermeerder zijn bezit en zijn kinderen, en zegen hem in wat U hem heeft gegeven.', 'O Allaah, increase his wealth and his children, and bless him in what You have given him.', 'فيدعى لمن خدمك أو قام على شأنك بالبركة في ماله وولده؛ قال أنس: فإني لمن أكثر الأنصار مالا وولدا.', 'Men smeekt voor wie je diende of je zaak behartigde om zegen in zijn bezit en kinderen; Anas zei: zo ben ik van de Ansaar met het meeste bezit en kinderen.', 'One supplicates for whoever served you or attended to your affair, for blessing in his wealth and children; Anas said: thus I am among the Ansaar with the most wealth and children.', 'قال أنس: فوالله إن مالي لكثير، وإن ولدي وولد ولدي ليتعادّون على نحو المائة.', 'Anas zei: bij Allaah, mijn bezit is veel geworden, en mijn kinderen en kleinkinderen tellen ongeveer honderd.', 'Anas said: by Allaah, my wealth became abundant, and my children and grandchildren number about one hundred.', 'ودعاؤه ﷺ لمن خدمه؛ لما', 'toestand', 'state/situation', 1, 204),('marriage', 'life', '«بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ»', 'Moge Allaah jou zegenen en Zijn zegen over jou laten neerdalen, en moge Hij jullie beiden in het goede verenigen.', 'May Allaah bless you and shower His blessings upon you, and may He unite you both in goodness.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء للمتزوج', 'gelegenheid', 'occasion', 1, 205),('marriage', 'life', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ»', 'O Allaah, ik vraag U het goede van haar en het goede van de aard waarmee U haar heeft geschapen, en ik zoek toevlucht bij U tegen haar kwaad en het kwaad van de aard waarmee U haar heeft geschapen.', 'O Allaah, I ask You for her good and the good of the disposition You created her upon, and I seek refuge in You from her evil and the evil of the disposition You created her upon.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند البناء بالأهل', 'gelegenheid', 'occasion', 1, 206),('marriage', 'life', '«بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا»', 'In de Naam van Allaah. O Allaah, houd de shaytaan van ons weg en houd de shaytaan weg van wat U ons schenkt.', 'In the Name of Allaah. O Allaah, keep Satan away from us and keep Satan away from what You grant us.', '', '', '', 'الأجر منصوص: إن قُدّر بينهما ولد لم يضره شيطان أبدا.', 'De beloning is uitdrukkelijk: als hun een kind wordt beschikt, zal geen shaytaan het ooit schaden.', 'The reward is stated: if a child is decreed for them, no devil will ever harm it.', 'الدعاء عند الجماع', 'gelegenheid', 'occasion', 1, 207),('newborn', 'life', 'كان النبي صلى الله عليه وسلم يؤتى بالصبيان فيحنّكهم ويدعو لهم بالبركة', 'De pasgeborene wordt bij de Profeet (vrede en zegeningen zij met hem) gebracht: hij verrichtte de tahniek en smeekte voor hem om zegen.', 'Newborns were brought to the Prophet (peace and blessings be upon him): he performed tahneek and supplicated for blessing upon them.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تحنيك المولود والدعاء له بالبركة', 'gelegenheid', 'occasion', 1, 208),('newborn', 'life', '«أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ»', 'Ik plaats jullie beiden onder de bescherming van de volmaakte Woorden van Allaah, tegen elke shaytaan en elk schadelijk dier, en tegen elk treffend (boos) oog — de bescherming van de kinderen.', 'I commend you both to the protection of Allaah''s perfect Words, from every devil and harmful creature, and from every evil eye — the protection of children.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تعويذ النبي ﷺ الحسن والحسين', 'gelegenheid', 'occasion', 1, 209),('sick_visit', 'state', '«لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللَّهُ»', 'Geen nood: het is een reiniging (van zonden), als Allaah het wil.', 'No harm: it is a purification (from sins), if Allaah wills.', 'يقولها العائد مؤمّلا للمريض أن مرضه تطهير من ذنوبه، وفي القصة أن رد البشارة بالتشاؤم لا يليق.', 'Zegt de bezoeker, hopend voor de zieke dat zijn ziekte een reiniging van zonden is; in het verhaal past het niet de blijde boodschap met pessimisme af te wijzen.', 'Said by the visitor, hoping for the sick that his illness is a purification of sins; in the account, rejecting the glad tidings with pessimism is unbecoming.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'يقول العائد للمريض', 'gelegenheid', 'occasion', 1, 210),('sick_visit', 'state', '«أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ»', 'Ik vraag Allaah, de Geweldige, de Heer van de geweldige Troon, om jou te genezen (zevenmaal bij de zieke wiens tijd nog niet gekomen is).', 'I ask Allaah the Magnificent, Lord of the Magnificent Throne, to cure you (seven times, for the sick whose time has not come).', '', '', '', 'الأجر منصوص: «إلا عوفي» ما لم يحضر أجله.', 'De beloning is uitdrukkelijk: ''of hij geneest'', zolang zijn tijd niet is gekomen.', 'The reward is stated: ''except that he is cured'', so long as his time has not come.', 'ما من عبد مسلم يعود', 'gelegenheid', 'occasion', 1, 211),('sick_visit', 'state', '«اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَاسَ، اشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا»', 'O Allaah, Heer van de mensen, neem het leed weg en genees; U bent de Genezer. Er is geen genezing behalve Uw genezing: een genezing die geen ziekte achterlaat.', 'O Allaah, Lord of mankind, remove the harm and cure; You are the Healer. There is no cure except Your cure: a cure that leaves no illness behind.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'رقية النبي ﷺ', 'gelegenheid', 'occasion', 1, 212),('death_funeral', 'state', '«إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَاخْلُفْ لِي خَيْرًا مِنْهَا»', 'Waarlijk, wij behoren Allaah toe en tot Hem keren wij terug. O Allaah, beloon mij in mijn beproeving en schenk mij iets beters ervoor in de plaats — dan schenkt Allaah hem iets beters.', 'Indeed we belong to Allaah and to Him we return. O Allaah, reward me in my affliction and give me better in its place — then Allaah grants him better.', '', '', '', 'الأجر منصوص: يؤجر في مصيبته ويُخلف خيرا منها؛ وقد أُخلفت أم سلمة رسولَ الله صلى الله عليه وسلم نفسه.', 'De beloning is uitdrukkelijk: hij wordt beloond in zijn beproeving en krijgt iets beters ervoor in de plaats; en Umm Salamah kreeg de boodschapper van Allaah (vrede en zegeningen zij met hem) in de plaats.', 'The reward is stated: he is rewarded in his affliction and given better in its place; and Umm Salamah was given the Messenger of Allaah (peace and blessings be upon him) in replacement.', 'ما يقول من أصابته مصيبة', 'gelegenheid', 'occasion', 1, 213),('death_funeral', 'state', '«قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ»', 'Allaah heeft het voorbeschikt, en wat Hij wil, doet Hij.', '', 'تقال بعد استفراغ الوسع والاستعانة بالله؛ فالحديث جمع العمل قبل النتيجة والتسليم بعدها، ومن دعاء القرآن بعد الخسارة قول أصحاب الجنة: ﴿عَسَى رَبُّنَا أَن يُبْدِلَنَا خَيْرًا مِّنْهَا إِنَّا إِلَى رَبِّنَا رَاغِبُونَ﴾ [القلم: 32].', 'Zegt men na het uitputten van de mogelijkheden en het zoeken van hulp bij Allaah; de hadieth verenigt het werk vóór het resultaat en de overgave erna.', 'Said after exhausting one''s effort and seeking Allaah''s help; the hadeeth unites work before the outcome and submission after it.', 'العلة منصوصة: «فإن لو تفتح عمل الشيطان»؛ فالكلمة تغلق على الشيطان بابه.', 'De reden is uitdrukkelijk: ''want (het woord) "als" opent het werk van de shaytaan''; het woord sluit dus de deur voor de shaytaan.', 'The reason is stated: ''for "if" opens the work of Satan''; the phrase thus shuts the door on Satan.', 'ما يقوله من فاته مطلوب أو أخفق في أمر أو خسر', 'gelegenheid', 'occasion', 1, 214),('death_funeral', 'state', '«لَقِّنُوا مَوْتَاكُمْ لَا إِلَهَ إِلَّا اللَّهُ»', 'Spoor jullie stervenden aan tot (het zeggen van): niets of niemand heeft het recht aanbeden te worden behalve Allaah (tawhied).', 'Prompt your dying ones to say: none has the right to be worshipped except Allaah.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تلقين المحتضر', 'gelegenheid', 'occasion', 1, 215),('death_funeral', 'state', '«اللَّهُمَّ اغْفِرْ لِأَبِي سَلَمَةَ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ»', 'O Allaah, vergeef (naam), verhef zijn rang onder de geleiden, wees zijn opvolger voor wie hij achterlaat, vergeef ons en hem, o Heer der werelden, maak zijn graf ruim voor hem en verlicht het voor hem.', 'O Allaah, forgive (name), raise his rank among the rightly guided, look after those he leaves behind, forgive us and him, O Lord of the worlds, make his grave spacious for him and illuminate it for him.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء عند إغماض الميت', 'gelegenheid', 'occasion', 1, 216),('death_funeral', 'state', '«اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَمِنْ عَذَابِ النَّارِ»', 'O Allaah, vergeef hem en wees hem genadig, schenk hem welzijn en scheld hem kwijt, ontvang hem eervol en maak zijn intrede ruim. Was hem met water, sneeuw en hagel en reinig hem van de zonden zoals U het witte kleed van vuil reinigt. Geef hem een betere woning dan zijn woning, een beter gezin dan zijn gezin en een betere echtgenote dan zijn echtgenote. Laat hem het Paradijs binnengaan en bescherm hem tegen de bestraffing van het graf en de bestraffing van het Vuur.', 'O Allaah, forgive him and have mercy on him, grant him wellbeing and pardon him, receive him honourably and make his entrance spacious. Wash him with water, snow and hail, and cleanse him of sins as You cleanse a white garment of filth. Give him a home better than his home, a family better than his family and a spouse better than his spouse. Admit him to Paradise and protect him from the punishment of the grave and of the Fire.', '', '', '', 'قال عوف: حتى تمنيت أن أكون أنا ذلك الميت؛ لعظم ما سمع من الدعاء.', '3awf zei: totdat ik wenste dat ik die dode was; wegens de grootsheid van de smeekbede die hij hoorde.', '3awf said: until I wished I were that deceased; because of the greatness of the supplication he heard.', 'الدعاء للميت في صلاة الجنازة', 'gelegenheid', 'occasion', 1, 217),('death_funeral', 'state', '«اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ، اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ، وَلَا تُضِلَّنَا بَعْدَهُ»', 'O Allaah, vergeef onze levenden en onze doden, de aanwezigen en de afwezigen, onze jongeren en onze ouderen, onze mannen en onze vrouwen. O Allaah, wie U van ons in leven laat, laat hem leven volgens de islam, en wie U van ons wegneemt, neem hem weg in geloof. O Allaah, onthoud ons zijn beloning niet en laat ons na hem niet dwalen.', 'O Allaah, forgive our living and our dead, those present and those absent, our young and our old, our males and our females. O Allaah, whomever of us You keep alive, let him live upon Islam, and whomever You take, take him upon faith. O Allaah, do not deprive us of his reward, and do not let us go astray after him.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء للميت في الصلاة عليه', 'gelegenheid', 'occasion', 1, 218),('death_funeral', 'state', '«بِسْمِ اللَّهِ، وَعَلَى سُنَّةِ رَسُولِ اللَّهِ»', 'In de Naam van Allaah en volgens de soennah van de boodschapper van Allaah (bij het neerleggen van de overledene in het graf).', 'In the Name of Allaah and upon the sunnah of the Messenger of Allaah (when placing the deceased in the grave).', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ما يقال عند إدخال الميت القبر', 'gelegenheid', 'occasion', 1, 219),('death_funeral', 'state', '«اسْتَغْفِرُوا لِأَخِيكُمْ، وَسَلُوا لَهُ التَّثْبِيتَ؛ فَإِنَّهُ الْآنَ يُسْأَلُ»', 'Vraag vergeving voor jullie broeder en vraag voor hem om standvastigheid, want hij wordt nu ondervraagd.', 'Seek forgiveness for your brother and ask that he be made steadfast, for he is now being questioned.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وبعد الدفن يقف على القبر ويقول', 'gelegenheid', 'occasion', 1, 220);